CREATE CACHED TABLE "PUBLIC"."CATEGORIA"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 3) NOT NULL,
    "NOME" CHARACTER VARYING(255),
    "NOME_NORMALIZADO" CHARACTER VARYING(255)
);
